def _qp(A, b, ridge, cap, budget):
    from scipy.optimize import minimize
    n = A.shape[1]
    (H, c) = (A.T @ A + ridge * np.eye(n), A.T @ b)

    def grad(w):
        return H @ w - c
    if budget == 0 or budget == n * cap:
        w = np.full(n, budget / n)
        return (w, float(np.min(grad(w)) if budget == 0 else np.max(grad(w))))
    scale = np.linalg.norm(H, ord=np.inf)
    res = minimize(lambda w: (0.5 * w @ H @ w - c @ w) / scale, np.full(n, budget / n), jac=lambda w: grad(w) / scale, bounds=[(0.0, cap)] * n, method='SLSQP', constraints={'type': 'eq', 'fun': lambda w: w.sum() - budget, 'jac': lambda w: np.ones(n)}, options={'ftol': 1e-13, 'maxiter': 500})
    w = res.x.copy()
    (lower, upper) = (w <= 1e-08 * cap, w >= (1 - 1e-08) * cap)
